/**
 * @fileoverview Test the usage of a private config
 * @author Sencha
 */
'use strict';

// ------------------------------------------------------------------------------
// Requirements
// ------------------------------------------------------------------------------

const rule = require('../../../lib/rules/no-private-config-usage'),
    RuleTester = require('eslint').RuleTester;

// ------------------------------------------------------------------------------
// Tests
// ------------------------------------------------------------------------------

const ruleTester = new RuleTester({
    settings: {
        extjs: {
            toolkit: 'modern',
            fromVersion: '6.0',
            toVersion: '7.9.0'
        }
    }
});
ruleTester.run('no-private-config-usage', rule, {

    valid: [
        {
            code: `
                Ext.define('MyCustomClass', { extend: 'Ext.util.Collection', customAutoFilter: true });
                Ext.define('MyCustomClass', { extend: 'Ext.util.Collection', customAutoGroup: true });
                Ext.define('MyCustomClass', { extend: 'Ext.util.Collection', customAutoSort: true });
                
                // TODO - these should be valid since these configs are public, fix doxi code
                // Ext.define('MyCustomClass', { extend: 'Ext.util.Collection', decoder: true });
                // Ext.define('MyCustomClass', { extend: 'Ext.util.Collection', groupers: true });
            `
        }
    ],

    invalid: [
        {
            code: `
                Ext.define('MyCustomClass', { extend: 'Ext.util.Collection', autoFilter: true });
                Ext.define('MyCustomClass', { extend: 'Ext.util.Collection', autoGroup: true });
                Ext.define('MyCustomClass', { extend: 'Ext.util.Collection', autoSort: true });
                
                // TODO - these should not be invalid since these configs are public, fix doxi code
                Ext.define('MyCustomClass', { extend: 'Ext.util.Collection', decoder: true });
                Ext.define('MyCustomClass', { extend: 'Ext.util.Collection', groupers: true });
            `,
            errors: [
                //{ message: /Usage of private config 'autoFilter' found for 'Ext.util.Collection'/ },
                { message: /Usage of private config 'autoGroup' found for 'Ext.util.Collection'/ },
                { message: /Usage of private config 'autoSort' found for 'Ext.util.Collection'/ },
                //{ message: /Usage of private config 'decoder' found for 'Ext.util.Collection'/ },
                //{ message: /Usage of private config 'groupers' found for 'Ext.util.Collection'/ }
            ]
        }
    ]
});
